import { useState } from "preact/hooks";
import type { MapPopupContentBlock, MapPopupCondition } from "../../maps/popup/mapPopupContent";
import type { MapAttributeSource } from "../../maps/attributes/mapFeatureAttributes";
import type { NormalizedField } from "../../data/normalizeData";
import { DraftInput } from "./MapDraftInput";
import { MapColorPicker } from "./MapColorPicker";

export function PopupContentEditor({ blocks, onChange, fieldSets, defaultSource, depth = 0 }: { blocks: MapPopupContentBlock[]; onChange: (blocks: MapPopupContentBlock[]) => void; fieldSets: Record<MapAttributeSource, NormalizedField[]>; defaultSource: MapAttributeSource; depth?: number }) {
    const [dragging, setDragging] = useState("");
    const patch = (id: string, change: Partial<MapPopupContentBlock>) => onChange(blocks.map(block => block.id === id ? { ...block, ...change } : block));
    const move = (from: number, to: number) => { if (to < 0 || to >= blocks.length) return; const next = [...blocks]; next.splice(to, 0, next.splice(from, 1)[0]); onChange(next); };
    const add = (type: MapPopupContentBlock["type"]) => {
        const first = fieldSets[defaultSource][0]?.key ?? "";
        onChange([...blocks, { id: `popup-${crypto.randomUUID().slice(0, 8)}`, type, fieldSource: defaultSource, ...(type === "field" ? { field: first, label: first } : type === "text" ? { text: "Additional details" } : type === "button" ? { label: "Show message", uiAction: { type: "showToast", message: "Feature selected" } } : type === "section" ? { label: "Details", children: [] } : type === "chart" ? { label: "Feature metrics", series: [] } : { label: type === "image" ? "Feature image" : "Open link", url: "" }) }]);
    };
    const conditionEditor = (block: MapPopupContentBlock, key: "when" | "colorWhen") => {
        const condition = block[key];
        const set = (change: Partial<MapPopupCondition> & { color?: string }) => patch(block.id, { [key]: { ...condition, ...change } });
        const source = condition?.fieldSource ?? block.fieldSource ?? defaultSource;
        return <details class="hp-popup-block-condition"><summary>{key === "when" ? "Visibility condition" : "Conditional color"}</summary><label><input type="checkbox" checked={!!condition} onChange={event => patch(block.id, { [key]: event.currentTarget.checked ? { field: fieldSets[source][0]?.key ?? "", fieldSource: source, operator: "=", value: "", ...(key === "colorWhen" ? { color: "#dc2626" } : {}) } : undefined })} />Enable condition</label>{condition && <><select aria-label={`${block.id} condition source ${key}`} value={source} onChange={event => set({ fieldSource: event.currentTarget.value as MapAttributeSource, field: "" })}>{["service", "powerbi", "joined"].map(value => <option>{value}</option>)}</select><select aria-label={`${block.id} condition field ${key}`} value={condition.field} onChange={event => set({ field: event.currentTarget.value })}><option value="">Choose field</option>{fieldSets[source].map(field => <option value={field.key}>{field.displayName}</option>)}</select><select aria-label={`${block.id} condition operator ${key}`} value={condition.operator} onChange={event => set({ operator: event.currentTarget.value as MapPopupCondition["operator"] })}>{["=", "!=", ">", "<", "contains"].map(value => <option>{value}</option>)}</select><DraftInput label="Compare with" value={String(condition.value)} onCommit={value => set({ value })} />{key === "colorWhen" && <MapColorPicker label="Conditional color" value={block.colorWhen?.color ?? "#dc2626"} onChange={color => set({ color })} />}</>}</details>;
    };
    return <div class="hp-popup-builder"><header><strong>{depth ? "Section contents" : "Popup Builder"}</strong><details class="hp-popup-add-content"><summary>Add Content +</summary><div role="menu" aria-label="Add popup content">{(["field", "text", "image", "link", "button", "chart", ...(depth < 2 ? ["section"] : [])] as MapPopupContentBlock["type"][]).map(type => <button type="button" role="menuitem" onClick={event => { add(type); (event.currentTarget.closest("details") as HTMLDetailsElement).open = false; }}>{type === "field" ? "Formatted field" : type === "chart" ? "Compact chart" : type === "section" ? "Conditional section" : type[0].toUpperCase() + type.slice(1)}</button>)}</div></details></header>{blocks.map((block, index) => {
        const source = block.fieldSource ?? defaultSource;
        return <details class="hp-popup-block" key={block.id} draggable onDragStart={() => setDragging(block.id)} onDragOver={event => event.preventDefault()} onDrop={event => { event.stopPropagation(); const from = blocks.findIndex(item => item.id === dragging); if (from >= 0) move(from, index); setDragging(""); }}><summary><span>⋮⋮ {block.label || block.type}</span><small>{block.type}</small></summary><div class="hp-popup-block-settings"><div class="hp-popup-block-order"><button type="button" aria-label={`Move popup block ${index + 1} up`} disabled={!index} onClick={() => move(index, index - 1)}>↑</button><button type="button" aria-label={`Move popup block ${index + 1} down`} disabled={index === blocks.length - 1} onClick={() => move(index, index + 1)}>↓</button><button type="button" aria-label={`Remove popup block ${index + 1}`} onClick={() => onChange(blocks.filter(item => item.id !== block.id))}>Remove</button></div><DraftInput label="Display name / title" value={block.label ?? ""} onCommit={label => patch(block.id, { label })} />
        {block.type !== "section" && <label><span>Field source</span><select aria-label={`Popup block ${index + 1} field source`} value={source} onChange={event => patch(block.id, { fieldSource: event.currentTarget.value as MapAttributeSource })}>{["service", "powerbi", "joined"].map(value => <option>{value}</option>)}</select></label>}
        {block.type === "field" && <><label><span>Field</span><select aria-label={`Popup block ${index + 1} field`} value={block.field ?? ""} onChange={event => patch(block.id, { field: event.currentTarget.value })}><option value="">Choose field</option>{fieldSets[source].map(field => <option value={field.key}>{field.displayName}</option>)}</select></label><label><span>Decimal precision</span><input type="number" min="0" max="10" value={block.decimals ?? 2} onChange={event => patch(block.id, { decimals: Number(event.currentTarget.value) })} /></label><DraftInput label="Units" value={block.units ?? ""} onCommit={units => patch(block.id, { units })} /><label><span>Date format</span><select value={block.dateFormat ?? ""} onChange={event => patch(block.id, { dateFormat: event.currentTarget.value ? event.currentTarget.value as "short" | "long" | "iso" : undefined })}><option value="">Numeric / text</option><option value="short">Short date</option><option value="long">Long date</option><option value="iso">ISO date</option></select></label></>}
        {block.type === "text" && <DraftInput label="Text template" multiline value={block.text ?? ""} onCommit={text => patch(block.id, { text })} />}
        {["image", "link"].includes(block.type) && <DraftInput label="HTTPS URL / template" value={block.url ?? ""} onCommit={url => patch(block.id, { url })} />}
        {block.type === "button" && <><label><span>Action</span><select value={block.uiAction?.type ?? "showToast"} onChange={event => patch(block.id, { uiAction: { type: event.currentTarget.value as "showToast" | "clearFilters", message: block.uiAction?.message } })}><option value="showToast">Show message</option><option value="clearFilters">Clear dashboard filters</option></select></label>{block.uiAction?.type === "showToast" && <DraftInput label="Action message" value={block.uiAction.message ?? ""} onCommit={message => patch(block.id, { uiAction: { type: "showToast", message } })} />}</>}
        {block.type === "chart" && <><button type="button" disabled={(block.series?.length ?? 0) >= 12} onClick={() => patch(block.id, { series: [...block.series ?? [], { field: fieldSets[source][0]?.key ?? "", fieldSource: source }] })}>Add chart value</button>{block.series?.map((item, seriesIndex) => <label><span>Chart value {seriesIndex + 1}</span><select value={item.field} onChange={event => patch(block.id, { series: block.series?.map((series, i) => i === seriesIndex ? { ...series, field: event.currentTarget.value } : series) })}>{fieldSets[source].map(field => <option value={field.key}>{field.displayName}</option>)}</select></label>)}</>}
        {["text", "field", "chart"].includes(block.type) && <MapColorPicker label="Text / chart color" value={block.color ?? "#182433"} onChange={color => patch(block.id, { color })} />}
        {block.type === "section" && <PopupContentEditor blocks={block.children ?? []} onChange={children => patch(block.id, { children })} fieldSets={fieldSets} defaultSource={defaultSource} depth={depth + 1} />}
        {conditionEditor(block, "when")}{["field", "text"].includes(block.type) && conditionEditor(block, "colorWhen")}</div></details>;
    })}<small>Click a feature on the map to preview current popup content. Drag blocks or use the arrow controls to reorder.</small></div>;
}
