import { aggregateValue } from "../../../data/aggregations";
import type { ComboChartComponent } from "../../../schema/hyperpbiSchema";
import type { ChartAdapter, ChartDatumBinding } from "./types";
import { baseOption, groupRows, semanticResult, sourceIndices } from "./shared";
import { formatValue } from "../../../utils/formatValue";

export const comboAdapter: ChartAdapter<ComboChartComponent>={type:"comboChart",fields:component=>[component.category,...component.series.map(series=>series.field)],build(component,rows,context){const categories=groupRows(rows,component.category,undefined,"count");const right=component.series.some(series=>series.axis==="right");const bindings:ChartDatumBinding[]=[];const series=component.series.map((definition,seriesIndex)=>({type:definition.chartType,name:definition.label??definition.field,yAxisIndex:definition.axis==="right"?1:0,selectedMode:"multiple",tooltip:definition.format?{valueFormatter:(value:unknown)=>formatValue(value,definition.format)}:undefined,data:categories.map((category,dataIndex)=>{const value=Number(aggregateValue(category.rows,definition.field,definition.aggregation??"sum")??0);bindings.push({seriesIndex,dataIndex,sourceRowIndices:sourceIndices(category.rows,context),field:component.category,value:category.rawKey});return value;})}));return semanticResult({...baseOption(context),tooltip:{trigger:"axis",confine:true},legend:{top:0},grid:{left:44,right:right?52:16,top:42,bottom:40,containLabel:true},xAxis:{type:"category",data:categories.map(item=>item.key)},yAxis:[{type:"value",position:"left"},...(right?[{type:"value" as const,position:"right" as const}]:[])],series},component,bindings);}};
